-- READ ONLY. Run AFTER the extension commits. Returns ONE result grid.
WITH expected(name) AS (VALUES ('recruitment_campaigns'),('recruitment_departments'),('recruitment_questions'),('recruitment_applications'),('application_answers'),('application_reviews'),('interview_appointments'),('interview_panel_members'),('notification_jobs'),('notifications'),('club_change_requests'),('club_channels'),('channel_members'),('channel_messages'),('channel_read_states'),('audit_logs')),
relations AS(SELECT e.name,c.oid,c.relrowsecurity FROM expected e LEFT JOIN pg_class c ON c.oid=to_regclass('public.'||e.name)),
rpcs AS(SELECT p.oid,p.oid::regprocedure::text AS signature,p.prosecdef,p.proconfig FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('clubspace_set_department_head','clubspace_clear_draft_answers','clubspace_transition_application','clubspace_remove_interviewer','clubspace_can_read_channel','clubspace_mark_channel_read','clubspace_channel_history','clubspace_decide_club_change','clubspace_claim_notification_jobs','clubspace_finish_notification_job','clubspace_mark_notification_read','clubspace_update_channel','clubspace_deliver_notification_job','clubspace_set_department_privacy'))
SELECT '01_table_count' AS section,jsonb_build_object('expected',16,'actual',count(oid),'all_rls_enabled',coalesce(bool_and(relrowsecurity),false)) AS result FROM relations
UNION ALL SELECT '02_table_access',jsonb_agg(jsonb_build_object('table',name,'exists',oid IS NOT NULL,'rls',relrowsecurity,'anon_select',has_table_privilege('anon',oid,'SELECT'),'authenticated_select',has_table_privilege('authenticated',oid,'SELECT'),'service_select',has_table_privilege('service_role',oid,'SELECT'),'service_insert',has_table_privilege('service_role',oid,'INSERT'),'service_update',has_table_privilege('service_role',oid,'UPDATE'),'service_delete',has_table_privilege('service_role',oid,'DELETE')) ORDER BY name) FROM relations
UNION ALL SELECT '03_rpc_count',jsonb_build_object('expected',14,'actual',count(*),'all_security_definer',bool_and(prosecdef)) FROM rpcs
UNION ALL SELECT '04_rpc_access',jsonb_agg(jsonb_build_object('signature',signature,'anon_execute',has_function_privilege('anon',oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',oid,'EXECUTE'),'service_execute',has_function_privilege('service_role',oid,'EXECUTE'),'config',proconfig) ORDER BY signature) FROM rpcs
UNION ALL SELECT '05_membership_admission',jsonb_build_object('service_direct_insert_should_be_false',has_table_privilege('service_role','public.club_memberships','INSERT'),'service_direct_role_update_should_be_false',has_column_privilege('service_role','public.club_memberships','role','UPDATE'),'service_move_department_should_be_true',has_column_privilege('service_role','public.club_memberships','department_id','UPDATE'))
UNION ALL SELECT '06_membership_role_check',jsonb_agg(pg_get_constraintdef(oid)) FROM pg_constraint WHERE conrelid='public.club_memberships'::regclass AND conname='club_memberships_role_v2_check'
UNION ALL SELECT '07_public_views',jsonb_build_object('campaign_view_exists',to_regclass('public.public_recruitment_campaigns') IS NOT NULL,'department_view_exists',to_regclass('public.public_recruitment_departments') IS NOT NULL)
UNION ALL SELECT '08_missing_general_channels',jsonb_build_object('count_should_be_zero',count(*)) FROM public.clubs c WHERE NOT EXISTS(SELECT FROM public.club_channels ch WHERE ch.club_id=c.club_id AND ch.kind='general')
UNION ALL SELECT '09_missing_department_channels',jsonb_build_object('count_should_be_zero',count(*)) FROM public.club_departments d WHERE NOT EXISTS(SELECT FROM public.club_channels ch WHERE ch.department_id=d.department_id AND ch.kind='department')
UNION ALL SELECT '10_private_channel_policy',jsonb_build_object('extra_grant_table_has_no_delegation_flag',NOT EXISTS(SELECT FROM information_schema.columns WHERE table_schema='public' AND table_name='channel_members' AND column_name='can_manage_members'),'history_and_access_rpcs_exist',(SELECT count(*)=2 FROM rpcs WHERE signature LIKE '%clubspace_channel_history(%' OR signature LIKE '%clubspace_can_read_channel(%'))
UNION ALL SELECT '10b_privacy_write_policy',jsonb_build_object('service_direct_privacy_update_should_be_false',has_column_privilege('service_role','public.club_departments','is_private','UPDATE'),'service_department_metadata_update_should_be_true',has_column_privilege('service_role','public.club_departments','name','UPDATE'))
UNION ALL SELECT '11_meeting_link_and_chat',jsonb_build_object('club_id_exists',EXISTS(SELECT FROM information_schema.columns WHERE table_schema='public' AND table_name='meetings' AND column_name='club_id'),'future_end_purge_trigger',EXISTS(SELECT FROM pg_trigger WHERE tgrelid='public.meeting_sessions'::regclass AND tgname='v2_purge_meeting_chat' AND tgenabled IN('O','A')))
ORDER BY section;
